function pas_dans_PV(carte)

  -- Si la carte est seul au alentour de la pile de victoire on renvoie false
  local carte_x = carte.getPosition().x
  local carte_y = carte.getPosition().y
  local carte_z = carte.getPosition().z

  if carte_x>30 and carte_x<31 and
     carte_y>1 and carte_y<2 and
     carte_z>2 and carte_z<3 then
       return false
  end

  return true

end


