      direction    = {0, 1, 0},
      type         = 3,
      size         = {0.5, 0.5, 0.5},
      max_distance = 0,
      debug        = false
  })

  for _, obj in ipairs(hitDeck) do
      if obj.hit_object.tag == "Deck" then
          local deckPV = obj.hit_object

          local position_bouton = {self.getPosition().x, self.getPosition().y+i, self.getPosition().z}

          deckPV.takeObject(
                {
                  guid = guid_carte,
                  position = position_bouton,
                  rotation = {0, 180, 0},
                  smooth = false,
                })

      end

      if obj.hit_object.tag == "Card" then
          local carte = obj.hit_object
          if carte.guid == guid_carte then self.putObject(carte) end
      end

  end

