function range_deck_dans_bouton(deck)

  local liste_carte = deck.getObjects()

  local der_carte = liste_carte[#liste_carte].guid

  for i = 1 , #liste_carte-1, 1 do

          local position_bouton = {self.getPosition().x, self.getPosition().y+i, self.getPosition().z}

          deck.takeObject(
                {
                  guid = liste_carte[i].guid,
                  position = position_bouton,
                  rotation = {0, 180, 0},
                  smooth = false,
                })
  end

  Wait.time(
    function()
      local carte_restante = getObjectFromGUID(der_carte)
      if carte_restante then self.putObject(carte_restante) end
    end,
    0.5)

end

function shuffleTable(t)
    for i = #t, 2, -1 do
        local n = math.random(i)
        t[i], t[n] = t[n], t[i]
    end
    return t
end

function tableLength(tbl) local count = 0 for _ in pairs(tbl) do count = count + 1 end return count end
